"""Build a user-input no-stop portfolio dashboard from saved OOS predictions."""

from __future__ import annotations

import json
import argparse
from pathlib import Path

import duckdb
from plotly.offline import get_plotlyjs

from walk_forward_hgb_all_stocks_twoday_10pct import DATA_PATH, PROJECT


OUTDIR = PROJECT / "artifacts" / "topn_no_stop_user_input_dashboard"
PREDICTIONS = PROJECT / "deliverables" / "all_stocks_intraday_excursion_regression" / "walk_forward_regression_predictions.csv"
OPTIMIZED_PREDICTIONS = PROJECT / "deliverables" / "short_regression_optimisation_walkforward" / "optimized_walkforward_predictions.csv"
MIN_THRESHOLD_PCT = 5.0


def html(payload: list[dict[str, object]], optimised: bool) -> str:
    plotly_js = get_plotlyjs()
    raw = json.dumps(payload, separators=(",", ":"))
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{'Optimised ' if optimised else ''}Top-N short portfolio dashboard</title>
<style>
body{{margin:0;background:#f4f7fb;color:#172033;font-family:Arial,sans-serif}}main{{max-width:1520px;margin:auto;padding:22px}}h1{{margin:0 0 6px;font-size:27px}}.note{{margin:0 0 16px;color:#46556e;line-height:1.45}}.box,.card,#equity,#heatmap,#hitHeatmap,#dayHeatmap,#yearHeatmap,#years,#daily{{background:#fff;border-radius:10px;box-shadow:0 1px 4px #17203318}}.controls{{display:grid;grid-template-columns:repeat(5,minmax(155px,1fr));gap:12px;padding:15px}}label{{display:grid;gap:5px;font-size:13px;font-weight:600}}input{{padding:8px;border:1px solid #cbd5e1;border-radius:6px;font-size:14px}}button{{border:0;border-radius:6px;background:#1769aa;color:#fff;font-weight:bold;padding:9px;cursor:pointer}}#warning{{margin-top:10px;color:#a2351f;font-weight:600}}#metrics{{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:15px 0}}.card{{padding:12px;font-size:12px}}.card b{{display:block;font-size:17px;margin-top:4px}}.chart{{margin-top:15px;min-height:450px}}#years,#daily{{padding:15px;margin-top:15px;overflow:auto}}table{{border-collapse:collapse;width:100%;font-size:13px}}th,td{{padding:7px;border-bottom:1px solid #e5eaf1;text-align:right}}th:first-child,td:first-child{{text-align:left}}th{{background:#f7f9fc}}summary{{cursor:pointer;font-size:18px;font-weight:700}}@media(max-width:900px){{.controls,#metrics{{grid-template-columns:1fr 1fr}}}}
.hm-title{{margin:0;padding:18px 18px 4px;font-size:18px}}.hm-subtitle{{margin:0;padding:0 18px 12px;color:#46556e;font-size:13px}}.hm-scroll{{overflow-x:auto;padding:0 18px 18px}}.hm-table{{min-width:850px;font-size:13px}}.hm-table th,.hm-table td{{text-align:center;min-width:58px;border:2px solid #fff;font-variant-numeric:tabular-nums}}.hm-table th:first-child,.hm-table td:first-child{{text-align:left;min-width:60px}}.hm-up{{background:#b7e4c7;color:#12412a;font-weight:700}}.hm-down{{background:#f8c5c5;color:#791d1d;font-weight:700}}.hm-empty{{background:#edf2f7;color:#718096}}
</style><script>{plotly_js}</script></head><body><main>
<h1>{'Optimised ' if optimised else ''}Top-N short: user allocation dashboard</h1>
<p class="note">Starting capital: <strong>₹100,000</strong>. A stock is eligible only when its saved out-of-sample predicted downside clears the entered threshold (minimum 5%). The dashboard takes the highest predicted eligible signals up to Top-N. <strong>Allocation per trade</strong> is applied separately to each selected stock. With leverage disabled, it funds only as many positions as the capital limit permits; with leverage enabled, total exposure may exceed 100%. Positions exit at target, stop-loss, or same-day close. If both target and stop are touched within one daily candle, the stop is used first because daily OHLC cannot establish the intraday sequence. Gross research only: costs, borrow, margin, liquidity and circuit limits are excluded.</p>
<section class="box controls"><label>Target (%)<input id="target" type="number" min="0.1" step="0.5" value="8"></label><label>Stop-loss (%)<input id="stop" type="number" min="0" step="0.5" value="5"><small>0 = disabled</small></label><label>Prediction threshold (%)<input id="threshold" type="number" min="5" step="0.5" value="5"></label><label>Predicted High cap (%)<input id="highcap" type="number" min="0" step="0.5" value="2"><small>0 = disabled</small></label><label>Top-N maximum trades/day<input id="topn" type="number" min="1" max="20" step="1" value="3"></label><label>Allocation per trade (%)<input id="allocation" type="number" min="1" max="100" step="1" value="20"></label><label>Allow leverage?<span><input id="leverage" type="checkbox"> Allow total exposure above 100%</span></label><button id="apply">Apply inputs</button></section>
<div id="warning"></div><section id="metrics"></section><div id="equity" class="chart"></div><h2 class="heatmap-heading">Monthly heatmaps</h2><p class="heatmap-note">Green indicates stronger results. Empty cells have no selected trades for that month.</p><div id="heatmap" class="chart"></div><div id="hitHeatmap" class="chart"></div><h2 class="heatmap-heading">Daily-pattern heatmap</h2><p class="heatmap-note">Shows the average daily portfolio return on selected signal days.</p><div id="dayHeatmap" class="chart"></div><h2 class="heatmap-heading">Year-wise heatmap</h2><p class="heatmap-note">Annual return, target-hit rate, drawdown, and trade count for the current inputs.</p><div id="yearHeatmap" class="chart"></div><section id="years"></section><section id="daily"></section>
<script>
const RAW={raw}.map(r=>({{...r,d:r.d.slice(0,10)}})), START=100000, MIN={MIN_THRESHOLD_PCT};
const el=id=>document.getElementById(id), fmt=n=>new Intl.NumberFormat("en-IN",{{maximumFractionDigits:0}}).format(n), pct=n=>`${{n.toFixed(2)}}%`;
function maxDD(e){{let peak=START,dd=0;for(const v of e){{peak=Math.max(peak,v);dd=Math.min(dd,(v/peak-1)*100)}}return dd}}
function pf(a){{let g=0,l=0;for(const x of a){{if(x>0)g+=x;else if(x<0)l-=x}}return l?g/l:null}}
function calc(){{const target=+el("target").value,stop=Math.max(0,+el("stop").value),threshold=Math.max(MIN,+el("threshold").value),highCap=Math.max(0,+el("highcap").value),topn=Math.max(1,Math.floor(+el("topn").value)),alloc=Math.max(0,Math.min(100,+el("allocation").value))/100,lev=el("leverage").checked;const cap=lev?topn:Math.floor(1/alloc+1e-10),limit=Math.min(topn,cap);let groups=new Map;for(const r of RAW){{if(r.p>=threshold&&(highCap===0||r.h<=highCap)){{if(!groups.has(r.d))groups.set(r.d,[]);groups.get(r.d).push(r)}}}}let days=[],trades=[];let equity=START;for(const [d,rows] of groups){{rows.sort((a,b)=>b.p-a.p||a.s.localeCompare(b.s));const chosen=rows.slice(0,limit);if(!chosen.length)continue;let returns=[];for(const r of chosen){{const targetTouched=r.down>=target*(1-1e-10),stopHit=stop>0&&r.up>=stop*(1-1e-10),targetHit=targetTouched&&!stopHit,ret=stopHit?-stop:targetHit?target:r.close;returns.push(ret);trades.push({{d,s:r.s,ret,targetHit,stopHit}})}}const dailyReturn=returns.reduce((a,x)=>a+x*alloc,0);const before=equity;equity*=1+dailyReturn/100;days.push({{d,r:dailyReturn,e:equity,before,n:chosen.length}})}}return {{target,stop,threshold,highCap,topn,alloc,lev,limit,days,trades}}}}
function render(){{const x=calc(), exposure=x.limit*x.alloc*100;const returns=x.trades.map(t=>t.ret), final=x.days.at(-1)?.e||START, total=(final/START-1)*100, years=Math.max((new Date(x.days.at(-1)?.d||"2020-01-01")-new Date(x.days[0]?.d||"2020-01-01"))/31557600000,1/365),cagr=((final/START)**(1/years)-1)*100;el("warning").textContent=x.limit<x.topn?`Capital limit funds only ${{x.limit}} positions/day at ${{(x.alloc*100).toFixed(1)}}% each; Top-${{x.topn}} is an upper limit.`:(x.lev&&exposure>100?`Leverage enabled: maximum gross exposure is ${{exposure.toFixed(1)}}%.`:"No leverage: maximum gross exposure is "+exposure.toFixed(1)+"%.");const metrics=[["Ending capital",`₹${{fmt(final)}}`],["Net P&L",`₹${{fmt(final-START)}}`],["Total return",pct(total)],["CAGR",pct(cagr)],["Max drawdown",pct(maxDD(x.days.map(d=>d.e)))],["Selected trades",x.trades.length],["Signal days",x.days.length],["Win rate",pct(100*returns.filter(r=>r>0).length/Math.max(1,returns.length))],["Profit factor",pf(returns)?.toFixed(3)||"-"],["Target / close exits",`${{x.trades.filter(t=>t.targetHit).length}} / ${{x.trades.filter(t=>!t.targetHit).length}}`]];el("metrics").innerHTML=metrics.map(([a,b])=>`<article class="card">${{a}}<b>${{b}}</b></article>`).join("");Plotly.react("equity",[{{x:x.days.map(d=>d.d),y:x.days.map(d=>d.e),mode:"lines",type:"scatter",line:{{width:2,color:"#1769aa"}},name:"Equity"}}],{{title:"Equity curve (₹100,000 starting capital)",yaxis:{{title:"Capital (₹)"}},height:430,margin:{{l:75,r:25,t:55,b:45}}}},{{responsive:true,displaylogo:false}});const yrs=[...new Set(x.days.map(d=>d.d.slice(0,4)))],mons=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],z=yrs.map(y=>mons.map((_,m)=>{{const rs=x.days.filter(d=>d.d.slice(0,4)===y&&new Date(d.d+"T00:00:00").getMonth()===m).map(d=>d.r/100);return rs.length?(rs.reduce((a,v)=>a*(1+v),1)-1)*100:null}}));const cap=Math.max(.01,...z.flat().filter(Number.isFinite).map(Math.abs));Plotly.react("heatmap",[{{type:"heatmap",z,x:mons,y:yrs,zmid:0,zmin:-cap,zmax:cap,colorscale:"RdYlGn",text:z.map(r=>r.map(v=>Number.isFinite(v)?v.toFixed(1):"")),texttemplate:"%{{text}}",hovertemplate:"%{{y}} / %{{x}}<br>%{{z:.2f}}%<extra></extra>"}}],{{title:"Compounded monthly portfolio return",height:450,margin:{{l:70,r:85,t:55,b:55}}}},{{responsive:true,displaylogo:false}});const rows=yrs.map(y=>{{const ds=x.days.filter(d=>d.d.slice(0,4)===y),ts=x.trades.filter(t=>t.d.slice(0,4)===y),end=ds.at(-1)?.e||START,start=ds[0]?.before||START,ret=(end/start-1)*100;return `<tr><td>${{y}}</td><td>${{ts.length}}</td><td>${{ds.length}}</td><td>${{pct(ret)}}</td><td>${{pct(maxDD(ds.map(d=>d.e)))}}</td><td>${{pct(100*ts.filter(t=>t.ret>0).length/Math.max(1,ts.length))}}</td></tr>`}}).join("");el("years").innerHTML=`<h2>Year-wise portfolio results</h2><table><thead><tr><th>Year</th><th>Trades</th><th>Signal days</th><th>Portfolio return</th><th>Max DD</th><th>Trade win rate</th></tr></thead><tbody>${{rows}}</tbody></table>`}}
function renderHitHeatmap(){{const x=calc(),yrs=[...new Set(x.days.map(d=>d.d.slice(0,4)))],mons=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],monthTrades=(y,m)=>x.trades.filter(t=>t.d.slice(0,4)===y&&new Date(t.d+"T00:00:00").getMonth()===m),z=yrs.map(y=>mons.map((_,m)=>{{const ts=monthTrades(y,m);return ts.length?100*ts.filter(t=>t.targetHit).length/ts.length:null}}));Plotly.react("hitHeatmap",[{{type:"heatmap",z,x:mons,y:yrs,zmin:0,zmax:100,colorscale:"RdYlGn",text:z.map(row=>row.map(v=>Number.isFinite(v)?v.toFixed(1)+"%":"")),texttemplate:"%{{text}}",hovertemplate:"%{{y}} / %{{x}}<br>Target hit rate: %{{z:.1f}}%<extra></extra>"}}],{{title:"Monthly target-hit rate",height:450,margin:{{l:70,r:85,t:55,b:55}}}},{{responsive:true,displaylogo:false}})}}
function renderHeatmaps(){{const x=calc(),yrs=[...new Set(x.days.map(d=>d.d.slice(0,4)))],mons=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],monthDays=(y,m)=>x.days.filter(d=>d.d.slice(0,4)===y&&new Date(d.d+"T00:00:00").getMonth()===m),monthTrades=(y,m)=>x.trades.filter(t=>t.d.slice(0,4)===y&&new Date(t.d+"T00:00:00").getMonth()===m),returns=yrs.map(y=>mons.map((_,m)=>{{const rs=monthDays(y,m).map(d=>d.r/100);return rs.length?(rs.reduce((a,v)=>a*(1+v),1)-1)*100:null}})),hits=yrs.map(y=>mons.map((_,m)=>{{const ts=monthTrades(y,m);return ts.length?100*ts.filter(t=>t.targetHit).length/ts.length:null}}));const table=(title,subtitle,values,kind)=>{{const cell=v=>{{if(v===null)return '<td class="hm-empty">—</td>';const good=kind==='return'?v>=0:v>=50;return `<td class="${{good?'hm-up':'hm-down'}}">${{v.toFixed(1)}}%</td>`}};return `<h3 class="hm-title">${{title}}</h3><p class="hm-subtitle">${{subtitle}}</p><div class="hm-scroll"><table class="hm-table"><thead><tr><th>Year</th>${{mons.map(m=>`<th>${{m}}</th>`).join('')}}</tr></thead><tbody>${{yrs.map((y,i)=>`<tr><td>${{y}}</td>${{values[i].map(cell).join('')}}</tr>`).join('')}}</tbody></table></div>`}};el("heatmap").innerHTML=table("Compounded monthly portfolio return","Green: positive month. Red: negative month. Values compound all selected daily portfolio returns within the month.",returns,"return");el("hitHeatmap").innerHTML=table("Monthly target-hit rate","Green: at least 50% of selected trades hit the chosen target. Red: below 50%.",hits,"hit")}}
function renderWeekdayHeatmap(){{const x=calc(),yrs=[...new Set(x.days.map(d=>d.d.slice(0,4)))],weekdays=["Mon","Tue","Wed","Thu","Fri"],weekdayIndex=[1,2,3,4,5],values=yrs.map(y=>weekdayIndex.map(day=>{{const rs=x.days.filter(d=>d.d.slice(0,4)===y&&new Date(d.d+"T00:00:00").getDay()===day).map(d=>d.r);return rs.length?rs.reduce((a,v)=>a+v,0)/rs.length:null}}));const cell=v=>{{if(v===null)return '<td class="hm-empty">—</td>';return `<td class="${{v>=0?'hm-up':'hm-down'}}">${{v.toFixed(2)}}%</td>`}};el("dayHeatmap").innerHTML=`<h3 class="hm-title">Average daily portfolio return by year and weekday</h3><p class="hm-subtitle">Each value is the mean portfolio return across selected signal days for that weekday; it is not compounded.</p><div class="hm-scroll"><table class="hm-table"><thead><tr><th>Year</th>${{weekdays.map(day=>`<th>${{day}}</th>`).join('')}}</tr></thead><tbody>${{yrs.map((y,i)=>`<tr><td>${{y}}</td>${{values[i].map(cell).join('')}}</tr>`).join('')}}</tbody></table></div>`}}
function renderYearAndDaily(){{const x=calc(),yrs=[...new Set(x.days.map(d=>d.d.slice(0,4)))],tradesByDate=new Map;for(const t of x.trades){{if(!tradesByDate.has(t.d))tradesByDate.set(t.d,[]);tradesByDate.get(t.d).push(t)}}const yearDD=ds=>{{let peak=ds[0]?.before||START,dd=0;for(const d of ds){{peak=Math.max(peak,d.e);dd=Math.min(dd,(d.e/peak-1)*100)}}return dd}},stats=yrs.map(y=>{{const ds=x.days.filter(d=>d.d.slice(0,4)===y),ts=x.trades.filter(t=>t.d.slice(0,4)===y),start=ds[0]?.before||START,end=ds.at(-1)?.e||start;return {{y,ret:(end/start-1)*100,hit:100*ts.filter(t=>t.targetHit).length/Math.max(1,ts.length),dd:yearDD(ds),trades:ts.length}}}}),yearCell=(v,type)=>{{const good=type==='ret'?v>=0:type==='hit'?v>=50:type==='dd'?v>=-10:null;const cls=good===null?'hm-empty':good?'hm-up':'hm-down';return `<td class="${{cls}}">${{type==='trades'?v:v.toFixed(1)+'%'}}</td>`}};el("yearHeatmap").innerHTML=`<h3 class="hm-title">Annual performance heatmap</h3><p class="hm-subtitle">Green means a positive annual return, at least 50% target hits, or drawdown no worse than 10%. Trade count is neutral.</p><div class="hm-scroll"><table class="hm-table"><thead><tr><th>Year</th><th>Return</th><th>Target hit</th><th>Max DD</th><th>Trades</th></tr></thead><tbody>${{stats.map(s=>`<tr><td>${{s.y}}</td>${{yearCell(s.ret,'ret')}}${{yearCell(s.hit,'hit')}}${{yearCell(s.dd,'dd')}}${{yearCell(s.trades,'trades')}}</tr>`).join('')}}</tbody></table></div>`;const dailyRows=[...x.days].reverse().map(d=>{{const ts=tradesByDate.get(d.d)||[],hits=ts.filter(t=>t.targetHit).length;return `<tr><td>${{d.d}}</td><td>${{ts.length}}</td><td>${{hits}} / ${{ts.length}}</td><td>${{pct(d.r)}}</td><td>₹${{fmt(d.e-d.before)}}</td><td>₹${{fmt(d.e)}}</td></tr>`}}).join('');el("daily").innerHTML=`<details><summary>Daily-wise portfolio results (${{x.days.length}} signal days)</summary><p class="note">Newest date first. Return and P&amp;L use the current Target, threshold, Top-N, allocation, and leverage inputs.</p><table><thead><tr><th>Date</th><th>Trades</th><th>Target hits</th><th>Portfolio return</th><th>Daily P&amp;L</th><th>Ending capital</th></tr></thead><tbody>${{dailyRows}}</tbody></table></details>`}}
function renderStopSummary(){{const x=calc(),stops=x.trades.filter(t=>t.stopHit).length,targets=x.trades.filter(t=>t.targetHit).length,closes=x.trades.length-targets-stops,cards=el("metrics").querySelectorAll(".card"),last=cards[cards.length-1];if(last)last.innerHTML=`Target / stop / close exits<b>${{targets}} / ${{stops}} / ${{closes}}</b>`}}
function refresh(){{render();renderStopSummary();renderHeatmaps();renderWeekdayHeatmap();renderYearAndDaily()}}
el("apply").addEventListener("click",refresh);for(const id of ["target","stop","threshold","highcap","topn","allocation","leverage"])el(id).addEventListener("change",refresh);refresh();
</script></main></body></html>"""


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--optimized", action="store_true", help="Use the nested walk-forward optimised short-regression predictions.")
    args = parser.parse_args()
    outdir = PROJECT / "artifacts" / ("topn_optimized_no_stop_user_input_dashboard" if args.optimized else "topn_no_stop_user_input_dashboard")
    outdir.mkdir(parents=True, exist_ok=True)
    prediction_file = OPTIMIZED_PREDICTIONS if args.optimized else PREDICTIONS
    prediction_path = prediction_file.resolve().as_posix().replace("'", "''")
    high_prediction_path = PREDICTIONS.resolve().as_posix().replace("'", "''")
    daily_path = DATA_PATH.resolve().as_posix().replace("'", "''")
    con = duckdb.connect()
    frame = con.execute(f"""
        SELECT cast(p.date AS DATE) AS date, p.symbol, p.predicted_excursion_pct,
               h.predicted_excursion_pct AS predicted_high_pct,
               100.0 * (1 - d.low / d.open) AS downside_pct,
               100.0 * (d.high / d.open - 1) AS upside_pct,
               100.0 * (1 - d.close / d.open) AS close_short_return_pct
        FROM read_csv_auto('{prediction_path}') p
        JOIN read_csv_auto('{high_prediction_path}') h
          ON cast(p.date AS DATE) = cast(h.date AS DATE) AND p.symbol = h.symbol
        JOIN read_parquet('{daily_path}') d
          ON cast(p.date AS DATE) = cast(d.date AS DATE) AND p.symbol = upper(d.symbol)
        WHERE {'p.target_kind = \'intraday_low\' AND' if not args.optimized else ''} h.target_kind = 'intraday_high'
          AND p.predicted_excursion_pct >= {MIN_THRESHOLD_PCT}
        ORDER BY date, p.predicted_excursion_pct DESC, p.symbol
    """).fetchdf()
    con.close()
    payload = [{"d": str(row.date), "s": row.symbol, "p": round(float(row.predicted_excursion_pct), 10), "h": round(float(row.predicted_high_pct), 10), "down": round(float(row.downside_pct), 10), "up": round(float(row.upside_pct), 10), "close": round(float(row.close_short_return_pct), 10)} for row in frame.itertuples(index=False)]
    (outdir / "eligible_predictions.json").write_text(json.dumps(payload, separators=(",", ":")), encoding="utf-8")
    dashboard_name = "topn_optimized_no_stop_user_input_dashboard.html" if args.optimized else "topn_no_stop_user_input_dashboard.html"
    (outdir / dashboard_name).write_text(html(payload, args.optimized), encoding="utf-8")
    print(f"eligible rows={len(payload):,}; sessions={frame.date.nunique():,}")
    print(f"Wrote {outdir / dashboard_name}")


if __name__ == "__main__":
    main()
